// Manual 8.3: materials compilation is source-driven by the exported Unity
// material JSON. app/data/materials.json is regenerated by verify_materials;
// this entry validates the compiled table without inventing parameters.
import { existsSync, readFileSync } from 'node:fs';
import { envFail, fail, pass } from './lib/gate.mjs';

const file = 'app/data/materials.json';
if (!existsSync(file)) envFail(`缺少 ${file}`);
const materials = JSON.parse(readFileSync(file, 'utf8'));
const list = Array.isArray(materials) ? materials : Object.values(materials);
if (list.length !== 34) fail(`材质数 ${list.length} != 34`);
const kinds = new Set(list.map(item => item.kind));
if (kinds.has('Unknown') || kinds.has('unknown')) fail('材质含 unknown');
pass(`materials compiled: ${list.length}, kinds ${[...kinds].sort().join(',')}`);
